custom_css:
.yaycheckout-digital-product {
	box-sizing: border-box;
	align-items: center;
}

.yaycheckout-digital-product-card {
	width: 100%;
	max-width: 920px;
	overflow: hidden;
	box-shadow: 0 9px 30px rgba(0, 0, 0, 0.2);
}

.yaycheckout-digital-product-aside {
	display: flex;
	flex-direction: column;
	min-height: 100%;
	box-sizing: border-box;
}

.yaycheckout-digital-product-aside > .wp-block-yaycheckout-order-summary {
	flex: 1 1 auto;
	display: flex;
	flex-direction: column;
}

.yaycheckout-digital-product-aside .wp-block-yaycheckout-order-summary-details {
	flex: 1 1 auto;
	display: flex;
	flex-direction: column;
}

.yaycheckout-digital-product-totals {
	margin-top: auto;
}

.yaycheckout-digital-product-aside .yaycheckout-coupon-form__code {
	height: 36px;
	min-height: 36px;
}

.yaycheckout-digital-product-aside .yaycheckout-coupon-form__apply {
	height: 36px;
	min-height: 36px;
}

.yaycheckout-digital-product-form {
	display: flex;
	flex-direction: column;
	min-height: 100%;
	box-sizing: border-box;
}

.yaycheckout-digital-product-submit {
	margin-top: auto;
}

.yaycheckout-digital-product .yaycheckout-place-order {
	display: flex;
	align-items: center;
	justify-content: center;
	height: 48px;
	box-sizing: border-box;
	white-space: nowrap;
}

.yaycheckout-digital-product .wp-block-columns {
	align-items: stretch;
}

.yaycheckout-checkout--floating-labels .yaycheckout-digital-product .yaycheckout-email .form-row > label {
	position: absolute;
	width: 1px;
	height: 1px;
	padding: 0;
	margin: -1px;
	overflow: hidden;
	clip: rect(0, 0, 0, 0);
	white-space: nowrap;
	border: 0;
	transform: none;
}

.yaycheckout-checkout--floating-labels .yaycheckout-digital-product .yaycheckout-email :is(.input-text, input) {
	min-height: var(--yaycheckout-input-height, 44px);
	padding-block: 0;
}

.yaycheckout-checkout--floating-labels .yaycheckout-digital-product .yaycheckout-email :is(.input-text, input)::placeholder {
	opacity: 1;
}
